profile = {}
for col in df.columns:
    s = df[col]
    profile[col] = {
        "dtype": str(s.dtype),
        "null_rate": s.isna().mean(),
        "distinct": s.nunique(),
        "top": s.mode().iloc[0] if not s.mode().empty else None,
    }

import json
print(json.dumps(profile, indent=2, default=str))
